def lost(n, name):
    c = "U%04d" % n
    code(c, "Нет связи с " + name, "lost_comm",
         m="Блок, который выставил код, ждал сообщений от этого блока по шине и не дождался: питание того блока, его разъём, жгут, шина, просадка напряжения.",
         r={"U0073": "если этот блок ещё и отключился от шины — искать шину и питание", "P0562": "низкое напряжение",
            **({"P0700": "коробка сообщила о своих ошибках"} if n == 101 else {}),
            **({"C0035": "если ABS молчит — датчики колёс, питание блока ABS"} if n == 121 else {})})


for n, name in MODULES.items():
    lost(n, name)

